/// Error type shared with the adapter runtime.
pub type Result<T> = an5_adapters::Result<T>;

/// Serializes an optional ORM input into the JSON shape the adapter expects.
fn to_value<T: serde::Serialize>(input: &Option<T>) -> Result<Option<serde_json::Value>> {
    match input {
        Some(v) => Ok(Some(serde_json::to_value(v)?)),
        None => Ok(None),
    }
}

/// Serializes an input into the row map used for writes.
fn to_map<T: serde::Serialize>(input: &T) -> Result<RowMap> {
    Ok(serde_json::to_value(input)?
        .as_object()
        .cloned()
        .unwrap_or_default())
}

/// Converts an adapter row into a generated model.
fn deserialize_row<T: DeserializeOwned>(row: RowMap) -> Result<T> {
    Ok(serde_json::from_value(serde_json::Value::Object(row))?)
}

/// Converts adapter rows into generated models.
fn deserialize_rows<T: DeserializeOwned>(rows: Vec<RowMap>) -> Result<Vec<T>> {
    rows.into_iter().map(deserialize_row).collect()
}

/// Main ORM context. Wraps the an5-adapters runtime.
#[derive(Clone)]
pub struct An5Client {
    adapter: An5Adapter,
}

impl An5Client {
    /// Connect and register this client's model to table mapping.
    pub async fn connect(connection_string: &str) -> Result<Self> {
        let adapter = An5Adapter::connect(connection_string).await?;
        Ok(Self::from_adapter(adapter))
    }

    /// Wrap an existing adapter, registering this client's metadata.
    pub fn from_adapter(adapter: An5Adapter) -> Self {
        let mut map = std::collections::HashMap::new();
        for (alias, table) in model_to_table_map() {
            map.insert(alias.to_string(), table.to_string());
        }
        let mut fields = std::collections::HashMap::new();
        for (alias, field_meta) in model_fields_map() {
            fields.insert(alias.to_string(), field_meta);
        }
        adapter.set_metadata(AdapterMetadata {
            model_to_table: map,
            model_fields: fields,
            ..Default::default()
        });
        Self { adapter }
    }

    /// The underlying adapter, for raw SQL, views and transactions.
    pub fn adapter(&self) -> &An5Adapter {
        &self.adapter
    }

    /// Dynamic access by model name, the equivalent of `db.table("User")`.
    pub fn table(&self, name: &str) -> TableClient {
        self.adapter.table(name)
    }

    /// Point a model at a different physical table (schema-less engines).
    pub fn with_table(self, model: &str, table: &str) -> Self {
        self.adapter.add_table_override(model, table);
        self
    }

    /// Resolve the table for a model.
    pub fn table_name(&self, model: &str) -> Option<String> {
        model_to_table(model).map(|t| t.to_string())
    }

    pub fn primary_key(&self, model: &str) -> Option<&'static str> {
        model_primary_key(model)
    }
}

/// Cosine similarity in [0,1]-ish range; 1.0 == identical direction.
pub fn cosine_similarity(a: &[f64], b: &[f64]) -> f64 {
    if a.len() != b.len() || a.is_empty() {
        return 0.0;
    }
    let mut dot = 0.0;
    let mut m1 = 0.0;
    let mut m2 = 0.0;
    for i in 0..a.len() {
        dot += a[i] * b[i];
        m1 += a[i] * a[i];
        m2 += b[i] * b[i];
    }
    if m1 == 0.0 || m2 == 0.0 {
        return 0.0;
    }
    dot / (m1.sqrt() * m2.sqrt())
}

/// Euclidean distance between two vectors.
pub fn euclidean_distance(a: &[f64], b: &[f64]) -> f64 {
    a.iter()
        .zip(b.iter())
        .map(|(x, y)| (x - y) * (x - y))
        .sum::<f64>()
        .sqrt()
}

/// Dot product between two vectors.
pub fn dot_product(a: &[f64], b: &[f64]) -> f64 {
    a.iter().zip(b.iter()).map(|(x, y)| x * y).sum()
}

/// Distance honouring the AN5 metric names.
pub fn vector_distance(a: &[f64], b: &[f64], metric: &str) -> f64 {
    match metric.to_lowercase().as_str() {
        "euclidean" => euclidean_distance(a, b),
        "dot" => -dot_product(a, b),
        _ => 1.0 - cosine_similarity(a, b),
    }
}

/// Standalone SQL builder for callers that prefer to drive their own driver.
#[derive(Clone)]
pub struct SqlBuilder {
    pub connection_string: String,
    pub dialect: Dialect,
}

impl SqlBuilder {
    pub fn new(connection_string: Option<String>) -> Self {
        let cs = connection_string.unwrap_or_else(crate::config::get_default_connection_string);
        let dialect = Dialect::detect(&cs);
        Self {
            connection_string: cs,
            dialect,
        }
    }

    pub fn table_name(&self, model: &str) -> Option<String> {
        model_to_table(model).map(|t| t.to_string())
    }

    pub fn primary_key(&self, model: &str) -> Option<&'static str> {
        model_primary_key(model)
    }

    pub fn quote_ident(&self, name: &str) -> String {
        self.dialect.quote_ident(name)
    }

    pub fn placeholder(&self, n: usize) -> String {
        self.dialect.placeholder(n)
    }
}

/// Typed queries for Order. Obtained via `An5Client::order()`.
#[derive(Clone)]
pub struct OrderTable {
    db: An5Client,
}

impl An5Client {
    /// Typed handle for Order.
    pub fn order(&self) -> OrderTable {
        OrderTable { db: self.clone() }
    }
}

impl OrderTable {
    /// The underlying adapter, for raw SQL or transactions.
    pub fn adapter(&self) -> &An5Adapter { self.db.adapter() }

    pub async fn find_many(&self, args: &OrderFindManyArgs) -> Result<Vec<Order>> {
        let rows = self
            .db
            .table("Order")
            .find_many(&FindManyArgs {
                r#where: to_value(&args.where_)?,
                order_by: to_value(&args.order_by)?,
                take: args.take.unwrap_or(0),
                skip: args.skip,
                select: args.select.as_ref().map(|s| serde_json::json!(s)),
                ..Default::default()
            })
            .await?;
        deserialize_rows(rows)
    }

    /// The rows nearest `vector`, each carrying a `distance`.
    pub async fn vector_search(&self, args: &OrderVectorSearchArgs) -> Result<Vec<(Order, f64)>> {
        let rows = self
            .db
            .table("Order")
            .vector_search(&VectorSearchArgs {
                vector: args.vector.iter().map(|v| *v as f64).collect(),
                take: args.take.unwrap_or(0),
                r#where: to_value(&args.where_)?,
                vector_field: args.vector_field.clone(),
                distance_metric: args.distance_metric.clone(),
                ..Default::default()
            })
            .await?;
        rows.into_iter().map(|row| {
            let distance = row.get("distance").and_then(serde_json::Value::as_f64)
                .ok_or("vector search returned no distance")?;
            Ok((deserialize_row(row)?, distance))
        }).collect()
    }

    pub async fn find_first(&self, args: &OrderFindFirstArgs) -> Result<Option<Order>> {
        let row = self
            .db
            .table("Order")
            .find_first(&FindManyArgs {
                r#where: to_value(&args.where_)?,
                order_by: to_value(&args.order_by)?,
                ..Default::default()
            })
            .await?;
        match row {
            Some(r) => Ok(Some(deserialize_row(r)?)),
            None => Ok(None),
        }
    }

    pub async fn find_unique(&self, args: &OrderFindUniqueArgs) -> Result<Option<Order>> {
        let row = self
            .db
            .table("Order")
            .find_unique(&FindManyArgs {
                r#where: to_value(&args.where_)?,
                ..Default::default()
            })
            .await?;
        match row {
            Some(r) => Ok(Some(deserialize_row(r)?)),
            None => Ok(None),
        }
    }

    pub async fn count(&self, args: &OrderFindUniqueArgs) -> Result<i64> {
        self.db
            .table("Order")
            .count(&CountArgs { r#where: to_value(&args.where_)? })
            .await
    }

    pub async fn create(&self, data: &OrderCreateInput) -> Result<Order> {
        let row = self
            .db
            .table("Order")
            .create(&to_map(data)?)
            .await?;
        deserialize_row(row)
    }

    pub async fn update(&self, args: &OrderUpdateArgs) -> Result<u64> {
        self.db
            .table("Order")
            .update(&UpdateArgs {
                r#where: to_value(&args.where_)?,
                data: serde_json::to_value(&args.data)?,
            })
            .await
    }

    pub async fn delete(&self, args: &OrderFindUniqueArgs) -> Result<u64> {
        self.db
            .table("Order")
            .delete_many(&DeleteManyArgs { r#where: to_value(&args.where_)? })
            .await
    }
}

